sketch matmul_transposed {
  symbols: M, N, K;
  tensors: A[K, M]: f32; B[N, K]: f32; C[M, N]: f32;
  constexpr: m0 = 128, n0 = 128, k0 = 32;

  @llm_hint("parallel", "grididx.x")
  for i_outer in range(0, M, m0):
    @llm_hint("parallel", "grididx.y")
    for j_outer in range(0, N, n0):
      d_tile = alloc([n0, m0], llm_hint=["fastest", "accumulator", "init_zero"])

      @llm_hint("pipeline")
      for k_outer in range(0, K, k0):
        b_tile = alloc([n0, k0], llm_hint=["fast", "input_cache"])
        a_tile = alloc([k0, m0], llm_hint=["fast", "input_cache"])

        load(B[j_outer:j_outer+n0, k_outer:k_outer+k0] -> b_tile)
        load(A[k_outer:k_outer+k0, i_outer:i_outer+m0] -> a_tile)

        gemm(b_tile, a_tile, dst=d_tile)

      c_tile = alloc([m0, n0], llm_hint=["fast", "output_buffer"])
      @llm_hint("vectorize")
      for i_inner in range(m0):
        @llm_hint("vectorize")
        for j_inner in range(n0):
          c_tile[i_inner, j_inner] = d_tile[j_inner, i_inner]

      store(c_tile -> C[i_outer:i_outer+m0, j_outer:j_outer+n0])
}

