sketch matmul_transeposed_both {
  symbols: M, N, K;
  tensors: A[K, M]: f32; B[N, K]: f32; C[M, N]: f32;

  BLOCK_SIZE_M = 128;
  BLOCK_SIZE_N = 128;
  BLOCK_SIZE_K = 32;

  @llm_hint("parallel", "grididx.x")
  for i_outer in range(0, ceil(M, BLOCK_SIZE_M)):
    @llm_hint("parallel", "grididx.y")
    for j_outer in range(0, ceil(N, BLOCK_SIZE_N)):

      c_tile = alloc([BLOCK_SIZE_M, BLOCK_SIZE_N], llm_hint=["fastest", "accumulator", "init_zero"])
      a_tile = alloc([BLOCK_SIZE_K, BLOCK_SIZE_M], llm_hint=["fast", "input_cache"])
      b_tile = alloc([BLOCK_SIZE_N, BLOCK_SIZE_K], llm_hint=["fast", "input_cache"])
      product = alloc([BLOCK_SIZE_N, BLOCK_SIZE_M], llm_hint=["temp_workspace"])
      product_transposed = alloc([BLOCK_SIZE_M, BLOCK_SIZE_N], llm_hint=["temp_workspace"])

      @llm_hint("pipeline")
      for k_outer in range(0, ceil(K, BLOCK_SIZE_K)):

        load(A[k_outer:k_outer+BLOCK_SIZE_K, i_outer:i_outer+BLOCK_SIZE_M] -> a_tile)
        load(B[j_outer:j_outer+BLOCK_SIZE_N, k_outer:k_outer+BLOCK_SIZE_K] -> b_tile)

        gemm(b_tile, a_tile, dst=product)
        transpose(product, dst=product_transposed)
        add(c_tile, product_transposed, c_tile)

      store(c_tile -> C[i_outer:i_outer+BLOCK_SIZE_M, j_outer:j_outer+BLOCK_SIZE_N])
}
